import json, re, sys, os

SESSION_DIR = "/Users/dyna/.minimax/v2/sessions/2026/10/27"
DIRS = {
    "mvs_0440be7b": "04-57-34-937-session_bXZzXzA0NDBiZTdiYWQ1MTQyMzRhNzBkYWUwYTQ5ZjgyZmM4",
    "mvs_06fd271c": "05-30-39-500-session_bXZzXzA2ZmQyNzFjNDNlYzQ1YTg5MTkzOWRlN2ZhZTI0Y2U1",
}

WRITE_RE = re.compile(r"(tee\s|sed\s+-i|>\s*\S|>>\s*\S|git\s+(add|commit|checkout|reset|stash)|patch\b|chmod )")


def load(sid):
    path = os.path.join(SESSION_DIR, DIRS[sid], "messages.jsonl")
    out = []
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if line:
                out.append(json.loads(line))
    return out


for sid in DIRS:
    msgs = load(sid)
    print("=" * 70)
    print(sid, "->", len(msgs), "messages")
    ts = [m["message"].get("timestamp") for m in msgs if m["message"].get("timestamp")]
    import datetime as dt
    tz = dt.timezone(dt.timedelta(hours=8))
    if ts:
        print("  first:", dt.datetime.fromtimestamp(min(ts) / 1000, tz).isoformat())
        print("  last :", dt.datetime.fromtimestamp(max(ts) / 1000, tz).isoformat())
    models = sorted({(m["message"].get("provider"), m["message"].get("model")) for m in msgs if m["message"].get("model")})
    print("  model:", models)
    # write-ish bash commands
    print("  --- bash commands that look like writes ---")
    hits = 0
    for m in msgs:
        for part in m["message"].get("content") or []:
            if isinstance(part, dict) and part.get("type") == "toolCall" and part.get("name") == "bash":
                cmd = (part.get("arguments") or {}).get("command", "")
                if WRITE_RE.search(cmd):
                    hits += 1
                    print("    *", cmd.replace("\n", " ")[:200])
    if not hits:
        print("    (none)")
    # assistant text
    print("  --- assistant text replies ---")
    for m in msgs:
        if m["message"].get("role") != "assistant":
            continue
        for part in m["message"].get("content") or []:
            if isinstance(part, dict) and part.get("type") == "text":
                t = part["text"].strip()
                if t:
                    print("    >>>", t[:900].replace("\n", " | "))

